import React from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import App from './App';
import { supabase } from './lib/supabase';

// Ignore Lock-broken / AbortError everywhere
function ignoreLockError(e) {
  const reason = e?.reason || e?.error || e;
  if (reason?.name === 'AbortError' || reason?.message?.includes('Lock broken')) {
    e?.preventDefault?.();
    e?.stopPropagation?.();
    console.warn('Lock error ignored:', reason.message);
    return true;
  }
  return false;
}
window.addEventListener('unhandledrejection', (event) => {
  if (ignoreLockError(event)) event.preventDefault();
});
window.addEventListener('error', (event) => {
  if (ignoreLockError(event)) event.preventDefault();
});

// Patch Supabase Realtime to use a safe lock if it accesses locks internally
if (supabase.realtime) {
  const origin = supabase.realtime;
  const origSubscribe = origin.subscribe?.bind(origin);
  if (origSubscribe) {
    origin.subscribe = function (...args) {
      // Wrap the subscribe call in a safe lock if possible
      return import('./lockHelper').then(({ safeLock }) =>
        safeLock('realtime-subscribe', () => origSubscribe.apply(origin, args))
      );
    };
  }
}

const container = document.getElementById('root');
const root = ReactDOM.createRoot(container);
root.render(<App />);
